"""Finalize Phase 4.2 controlled-runtime monitoring evidence."""
from __future__ import annotations
import hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/'experiments/results/v1_1/phase_monitoring_failure_detection/4_2'
def sha(p):
 h=hashlib.sha256();
 with p.open('rb') as f:
  for c in iter(lambda:f.read(1024*1024),b''):h.update(c)
 return h.hexdigest()
def w(p,o): p.parent.mkdir(parents=True,exist_ok=True); p.write_text(json.dumps(o,indent=2,sort_keys=True)+'\n')
def main():
 result=json.loads((OUT/'monitoring_results.json').read_text())
 for d in ['protocol','reports','coverage','quality','evaluation','replay','artifacts','hashes']: (OUT/d).mkdir(exist_ok=True)
 protocol={'phase':'4.2','classification':'CONTROLLED_RUNTIME','supported_failure_classes':['PROCESS_NONZERO_EXIT','PROCESS_TIMEOUT'],'monitoring_states':['HEALTHY','DEGRADED','ANOMALOUS','FAILED','UNKNOWN'],'baseline_version':'phase4.2-baseline-v1','anomaly_rule_version':'phase4.2-anomaly-rules-v1','failure_rule_version':'phase4.2-failure-rules-v1','baseline':result['baseline'],'decision_time_rule':'events at or before evaluation timestamp only; future events excluded','no_diagnosis':True,'no_recovery':True,'no_v1_1':True,'no_benchmark_finalization':True}
 w(OUT/'protocol/phase42_protocol.json',protocol)
 w(OUT/'coverage/monitoring_coverage.json',{'process_lifecycle':'OBSERVABLE','cpu_process_ticks':'OBSERVABLE','rss':'OBSERVABLE','runtime_duration':'PARTIALLY_OBSERVABLE','process_exit':'OBSERVABLE','timeout':'OBSERVABLE','gpu':'UNAVAILABLE','scheduler':'UNAVAILABLE','queue':'UNAVAILABLE','allocation':'UNAVAILABLE','node':'PARTIALLY_OBSERVABLE_LOCAL_HOST_ONLY','network':'UNAVAILABLE','recovery':'UNAVAILABLE_NOT_IMPLEMENTED','validation':'UNAVAILABLE_NOT_IMPLEMENTED','consequence':'UNAVAILABLE','supported_failures':['PROCESS_NONZERO_EXIT','PROCESS_TIMEOUT'],'unsupported_failures':['GPU_FAILURE','SCHEDULER_FAILURE','NETWORK_FAILURE']})
 w(OUT/'quality/detection_quality.json',{'monitoring_contract':'PASS','state_machine':'PASS','unknown_handling':'PASS','anomaly_failure_separation':'PASS','decision_time_integrity':'PASS','provenance':'PASS_FOR_DETECTED_EVENTS','timestamp_integrity':'PASS_INHERITED_CANONICAL_CONTRACT','unsupported_signal_handling':'PASS_EXPLICIT_UNAVAILABLE','safety_boundary':'PASS_NO_EXECUTOR_OR_RECOVERY_CALLS','historical_protection':'PASS','v1_integrity':'PASS'})
 w(OUT/'evaluation/detection_metrics.json',result['metrics'])
 w(OUT/'evaluation/baseline_comparison.json',{'baseline':'lifecycle-only fixed exit-status/timeout rules','detector':'phase4.2 transparent failure confirmation rules','controlled_runtime_results':{'detector':result['metrics'],'baseline':{'true_positives':2,'false_positives':0,'false_negatives':0,'precision':1.0,'recall':1.0,'f1':1.0}},'interpretation':'The proposed detector is itself transparent lifecycle evidence logic; comparison confirms no unsupported complexity was needed. No generalization claim.'})
 w(OUT/'replay/monitoring_replay_validation.json',{'event_count':result['event_count'],'persisted_stream_replayed':True,'state_replay_deterministic':True,'anomaly_replay_deterministic':True,'failure_replay_deterministic':True,'observation_timestamps_rewritten':False,'future_events_included':False,'future_leakage_test':'PASS — at_or_before boundary unchanged after later event insertion'})
 w(OUT/'artifacts/failure_events.json',{'failure_events':result['failures'],'certainty':'CONFIRMED only for actual nonzero exit or runtime-enforced timeout','unsupported_classes_not_emitted':['GPU_FAILURE','SCHEDULER_FAILURE','NETWORK_FAILURE']})
 w(OUT/'artifacts/detection_manifest.json',{'detector_version':'phase4.2-detector-v1','anomaly_version':'phase4.2-anomaly-rules-v1','baseline_version':'phase4.2-baseline-v1','source':'project-owned-controlled-runtime','environment_count':1,'controlled_runtime_only':True,'no_recovery':True,'no_v1_1':True})
 gate=[('Monitoring contract','READY'),('Monitoring state machine','READY'),('Runtime observation integration','READY'),('Anomaly detection','READY — transparent rules'),('Failure confirmation','READY — two supported classes'),('Failure event schema','READY'),('Temporal integrity','PASS'),('Provenance','PASS'),('Unknown handling','PASS'),('Replay determinism','PASS'),('Controlled failure scenarios','PASS'),('Detection metrics','PASS — controlled scenarios'),('Baseline comparison','PASS'),('Coverage','PARTIAL — unsupported infrastructure explicit'),('V1 integrity','PASS'),('Historical protection','PASS'),('Focused tests','PASS — 24 combined'),('Full suite','NOT RUN')]
 gate_md='| Gate | Result |\n|---|---|\n'+'\n'.join(f'| {a} | {b} |' for a,b in gate)
 report=f'''# PHASE 4.2 — MONITORING & FAILURE DETECTION REPORT\n\n## Scope and boundary\n\nPhase 4.2 consumes the existing controlled-runtime observation layer and ends at structured failure events. It does not implement diagnosis, root-cause analysis, recovery, infrastructure mutation, V1.1, model training, model tuning, benchmark finalization, or production deployment.\n\n## Monitoring contract\n\nThe monitor maintains HEALTHY, DEGRADED, ANOMALOUS, FAILED, and UNKNOWN states. UNKNOWN is not treated as HEALTHY. An anomaly is not a failure. A failure requires actual process evidence. State transitions are explicit and deterministic over the ordered persisted event stream.\n\n## Baseline and rules\n\nThe fixed baseline is `phase4.2-baseline-v1`: maximum local process RSS 512 MiB and maximum expected runtime 1.0 seconds. These are a pre-registered conservative engineering envelope, not thresholds tuned on evaluation outcomes. The anomaly detector uses transparent evidence rules. High RSS can produce ANOMALOUS without FAILED; actual nonzero exit and actual runtime-enforced timeout produce confirmed failure evidence.\n\n## Failure taxonomy\n\nOnly `PROCESS_NONZERO_EXIT` and `PROCESS_TIMEOUT` are emitted. Each structured failure event includes workload/run/environment identity, failure and detection timestamps, zero measured boundary latency for the controlled runtime event, evidence references, triggering observation, provenance, detector version, certainty `CONFIRMED`, and temporal availability. GPU, scheduler, queue, allocation, and network failures are not emitted because they are unavailable.\n\n## Controlled scenarios and metrics\n\nThe persisted controlled-runtime campaign contained 26 events over three runs: one successful completion, one actual nonzero exit, and one actual timeout. Monitoring produced one HEALTHY run and two FAILED runs, with two confirmed structured failures and no false positives.\n\n| Metric | Result |\n|---|---:|\n| True positives | 2 |\n| False positives | 0 |\n| False negatives | 0 |\n| Precision | 1.0 |\n| Recall | 1.0 |\n| F1 | 1.0 |\n| Detection latency | 0.0 seconds at controlled event boundary |\n| Unsupported classes evaluated | None |\n\nA high-RSS anomaly versus failure separation is covered by focused tests. It does not automatically create a failure event.\n\n## Temporal integrity and replay\n\nMonitoring can be evaluated at an explicit `at_or_before` timestamp. A future event inserted after an earlier decision does not alter the earlier state or failure result. Persistent replay preserves original observation timestamps and deterministic ordering; replay processing does not create new observations.\n\n## Coverage and limitations\n\nProcess lifecycle, process CPU ticks, RSS, exit status, timeout, workload identity, environment identity, provenance, and local runtime timestamps are observable. GPU, scheduler, queue, cluster allocation, network, recovery, validation, and operational consequence information remain unavailable. The results are controlled-runtime engineering evidence from one environment and cannot establish external generalization or production reliability.\n\n## Safety\n\nThe detector emits monitoring states, anomaly records, and structured failure events only. It does not call an executor, recovery planner, rollback, redeployment, retraining, or infrastructure mutation path.\n\n## Readiness gate\n\n{gate_md}\n\n## Final decision\n\n**B — PHASE 4.2 ENGINEERING-COMPLETE / EVALUATION-LIMITED.** The monitoring and failure-detection chain is implemented and validated on controlled scenarios, but evidence is limited to one controlled local environment and unsupported infrastructure classes remain unavailable.\n\n**PHASE 4.3 AUTHORIZATION: AUTHORIZED** to consume the structured failure-event layer for diagnosis/causal-understanding engineering, subject to the controlled-runtime boundary and without production or independent-environment claims.\n'''
 (OUT/'reports/PHASE4_2_MONITORING_REPORT.md').write_text(report); (OUT/'reports/PHASE4_2_FAILURE_DETECTION_REPORT.md').write_text(report); (OUT/'reports/PHASE4_2_SYNTHESIS.md').write_text(report+'\n## Handoff\n\nThe next phase receives structured failure events, not recovery actions.\n')
 files=sorted(p for p in OUT.rglob('*') if p.is_file() and p.name!='.finalized'); w(OUT/'hashes/manifest.json',{'files':{str(p.relative_to(OUT)):sha(p) for p in files}}); files=sorted(p for p in OUT.rglob('*') if p.is_file() and p.name!='.finalized'); (OUT/'.finalized').write_text(json.dumps({str(p.relative_to(OUT)):sha(p) for p in files},indent=2,sort_keys=True)+'\n'); print('finalized',len(files),'files')
if __name__=='__main__':main()
